using System;using System.Threading.Tasks;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UI;using Demo5.FrontEnd;
public static class PreviewOpeningNote {
 public static string Conclusion(){var c=UnityEngine.Object.FindAnyObjectByType<SettlementController>();c.Opening.Close();c.Opening.State.SurveyReturned=true;c.Opening.Act();Canvas.ForceUpdateCanvases();if(c.Opening.EventBody.preferredHeight>400)throw new Exception("Conclusion overflow");return "Conclusion fits: "+c.Opening.EventBody.preferredHeight;}
 public static async Task<string> Run(){var c=UnityEngine.Object.FindAnyObjectByType<SettlementController>();CampaignSaveStore.TestDirectory=System.IO.Path.GetFullPath("Temp/OpeningChapterVerification");try{var saved=CampaignSaveStore.Read(0,c);if(!saved.CanLoad)throw new Exception(saved.Error);saved.Data.Opening=new SavedOpeningChapter{Enabled=true,FirstReturn=true};CampaignPersistence.Prepare(saved.Data,c);}finally{CampaignSaveStore.TestDirectory=null;}SceneManager.LoadScene("Settlement");await Task.Delay(500);c=UnityEngine.Object.FindAnyObjectByType<SettlementController>();c.Opening.Act();Canvas.ForceUpdateCanvases();var body=c.Opening.EventBody;if(body.preferredHeight>body.rectTransform.rect.height)throw new Exception("Body overflow "+body.preferredHeight);if(c.Main.alpha!=0)throw new Exception("HUD visible");return "Compact note fits: "+body.preferredHeight+" / "+body.rectTransform.rect.height+". Preview fixture only; saved game unchanged.";}
}

